    @given(st.integers(), st.integers(), st.integers())
    def test_associativity(self, a, b, c):
        """(a + b) + c == a + (b + c)"""
        assert add(add(a, b), c) == add(a, add(b, c))

    @given(st.integers())
    def test_identity(self, a):
        """a + 0 == a"""
